    iS += Math.sin(d1*f*0.7+t*sp*0.6+1.5)*w;
    aS2 += Math.sin(d2*f*1.3-t*sp*0.8+2.0)*w;
    iS2 += Math.sin(d2*f*0.5+t*sp*0.4+0.8)*w;
  }
  const act = aS/9.5, inh = iS/9.5, act2 = aS2/9.5, inh2 = iS2/9.5;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2 + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2;
